// ===========================================================================
//  BlurSwitchCS.dll  —  decompiled C#
// ---------------------------------------------------------------------------
//  Binary : 10-extracted/code$getextractpath$/source/blurswitchcs.dll
//           PE32, .NET/CIL  (v4.0.30319), assembly BlurSwitchCS v1.0.0.0,
//           TargetFramework .NETFramework v4.6.1, Authenticode-signed 2022-04-26
//  PDB    : E:\LenovoHotkeysSvcGit\gitcode\lenovohotkeysvc\LenovoKBDHetkey\
//           BlurSwitchCS\obj\Release\BlurSwitchCS.pdb
//
//  Fidelity: class name, method names (ToggleBlurSwitch, SendMessageAsync,
//  OpenAsync), every string literal, all referenced types and the assembly
//  attributes are taken verbatim from the assembly's metadata (#Strings/#US
//  heaps, TypeRef/MemberRef). Control flow and the numeric values of the
//  STATUS_* constants are RECONSTRUCTED from the referenced member set
//  (AppServiceConnection / AppServiceResponse / ValueSet / Task.AsTask /
//  Wait / get_Result / AppServiceConnectionStatus / AppServiceResponseStatus)
//  and are marked [INFERENCE].
// ===========================================================================
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Windows.ApplicationModel.AppService;      // AppServiceConnection, AppServiceResponse, AppServiceConnectionStatus, AppServiceResponseStatus
using Windows.Foundation;
using Windows.Foundation.Collections;            // ValueSet

namespace BlurSwitchCS
{
    public class BlurSwitchCS
    {
        // ---- status codes (field names verbatim from #Strings heap; the CIL
        //      constant values are not recoverable from metadata alone). [INFERENCE]
        public const int STATUS_SET_BLUR_OFF_OK = 0x00;   // blur switched OFF successfully
        public const int STATUS_SET_BLUR_ON_OK  = 0x01;   // blur switched ON  successfully
        public const int STATUS_EXCEPTION       = 0x02;   // managed exception caught
        public const int STATUS_SVR_REPOND_ERR  = 0x03;   // server responded with error [sic: REPOND]
        public const int STATUS_SET_FEATURE_ERR = 0x04;   // server returned "BlurError"
        public const int STATUS_RETURN_ERR      = 0x05;   // malformed/absent result
        public const int STATUS_CONNECT_SVR_ERR = 0x06;   // AppService connection failed
        public const int STATUS_SET_TIMEOUT     = 0x07;   // send/open timed out

        // ---- literals recovered from the #US heap -------------------------
        private const string AppServiceName    = "Lenovo.CameraControlBackgroundService";
        private const string PackageFamilyName = "E0469640.SmartAppearance_5grkq8ppsgwt4";
        private const string RequestKey        = "Key";                 // request ValueSet key
        private const string RequestCommand    = "ToggleBlurSwitch";    // request ValueSet value
        private const string ResultKey         = "Result";              // response ValueSet key
        private const string ResultBlurOff     = "BlurOff";
        private const string ResultBlurOn      = "BlurOn";
        private const string ResultBlurError   = "BlurError";

        // [INFERENCE] poll timeout for the async send (STATUS_SET_TIMEOUT exists)
        private const int TimeoutMs = 5000;

        /// <summary>Opens the AppService connection to the SmartAppearance package.</summary>
        /// <returns>connection on success, null on failure</returns>
        private static AppServiceConnection OpenAsync()
        {
            var conn = new AppServiceConnection();
            conn.AppServiceName   = AppServiceName;
            conn.PackageFamilyName = PackageFamilyName;

            Task<AppServiceConnectionStatus> task = conn.OpenAsync().AsTask();
            if (!task.Wait(TimeoutMs))            // WaitHandle.Wait -> timeout
                return null;                      // -> STATUS_SET_TIMEOUT
            if (task.Result != AppServiceConnectionStatus.Success)  // op_Equality
                return null;                      // -> STATUS_CONNECT_SVR_ERR
            return conn;
        }

        /// <summary>Sends the ToggleBlurSwitch command and maps the reply to a status code.</summary>
        private static int SendMessageAsync(AppServiceConnection conn)
        {
            var message = new ValueSet();
            message.Add(RequestKey, RequestCommand);      // { "Key" : "ToggleBlurSwitch" }

            Task<AppServiceResponse> task = conn.SendMessageAsync(message).AsTask();
            if (!task.Wait(TimeoutMs))
                return STATUS_SET_TIMEOUT;

            AppServiceResponse response = task.Result;
            if (response.Status != AppServiceResponseStatus.Success)   // get_Status
                return STATUS_SVR_REPOND_ERR;

            if (!response.Message.ContainsKey(ResultKey))               // get_Message/ContainsKey
                return STATUS_RETURN_ERR;

            string result = response.Message[ResultKey].ToString();     // get_Item / Object.ToString()
            if (string.IsNullOrEmpty(result))                           // IsNullOrEmpty
                return STATUS_RETURN_ERR;

            if (result == ResultBlurOn)      return STATUS_SET_BLUR_ON_OK;   // String.op_Equality
            if (result == ResultBlurOff)     return STATUS_SET_BLUR_OFF_OK;
            if (result == ResultBlurError)   return STATUS_SET_FEATURE_ERR;
            return STATUS_RETURN_ERR;
        }

        /// <summary>Toggles the camera background-blur state. Entry point.</summary>
        /// <returns>STATUS_* code (logged by the caller as "retBlur=%d")</returns>
        public static int ToggleBlurSwitch()
        {
            try
            {
                AppServiceConnection conn = OpenAsync();
                if (conn == null)
                    return STATUS_CONNECT_SVR_ERR;

                using (conn)                                  // IDisposable.Dispose
                {
                    return SendMessageAsync(conn);
                }
            }
            catch (Exception)                                 // STATUS_EXCEPTION
            {
                return STATUS_EXCEPTION;
            }
        }
    }
}

